    if abs(x) < 1e-9:
        return 0.0
    return x

def where(r):
    if r == 0 or r == 180:
        return "on the x-axis"
    elif r == 90 or r == 270:
        return "on the y-axis"
    elif r < 90:
        return "quadrant I"
    elif r < 180:
        return "quadrant II"
    elif r < 270:
        return "quadrant III"
    else:
        return "quadrant IV"

def show(label, deg):
    r = deg % 360
    t = math.radians(deg)
    c = clean(math.cos(t))
    s = clean(math.sin(t))
    print(f"{label}: {deg} degrees")
    print(f"  reduce: {deg} % 360 = {r}, {where(r)}")
    print(f"  P = (cos, sin) = ({c:.4f}, {s:.4f})")
    if c == 0:
        print("  tan = sin / cos is undefined, since cos = 0")
    else:
        print(f"  tan = sin / cos = {clean(s / c):.4f}")

show("Example 1", 60)
show("Example 2", 90)
show("Example 3", 180)
show("Example 5", 150)
show("Example 6", -90)
