import math

def clean(x):
    if abs(x) < 1e-9:
        return 0.0
    return x

def where(r):
    if r == 0 or r == 180:
        return "on the x-axis"
    elif r == 90 or r == 270:
        return "on the y-axis"
    elif r < 90:
        return "quadrant I"
    elif r < 180:
        return "quadrant II"
    elif r < 270:
        return "quadrant III"
    else:
        return "quadrant IV"

n = int(input())
for i in range(n):
    deg = int(input())
    r = deg % 360
    t = math.radians(deg)
    c = clean(math.cos(t))
    s = clean(math.sin(t))
    print(f"Angle {deg}")
    print(f"  reduced: {r}, {where(r)}")
    print(f"  P = ({c:.4f}, {s:.4f})")
    if c == 0:
        print("  tan is undefined")
    else:
        print(f"  tan = {clean(s / c):.4f}")
